query.base:
TS metrics-gcp.bigquery.otel-*
// slots/allocated is dual-reported on `global`; keep the bigquery_project copy only.
// Reserved usage only: on-demand usage has no reservation label and no reported ceiling.
| WHERE resource.attributes.gcp.resource_type == "bigquery_project"
  AND attributes.reservation IS NOT NULL AND attributes.reservation != ""
// Stage 1: one value per minute per logical series (MAX collapses fragmented TSIDs of the same series)
| STATS allocated = MAX(MAX_OVER_TIME(`metrics.bigquery.googleapis.com/slots/allocated`)),
        ceiling = MAX(MAX_OVER_TIME(`metrics.bigquery.googleapis.com/slots/max_assigned`))
    BY @timestamp = TBUCKET(1 minute), attributes.reservation, resource.attributes.location, resource.attributes.project_id, attributes.job_type
// Stage 2: per reservation per minute. Usage adds up across assigned projects and job types;
// the autoscale ceiling is the same reservation value on every assignment, so take MAX (not SUM).
| STATS allocated = SUM(allocated), ceiling = MAX(ceiling)
    BY @timestamp, attributes.reservation, resource.attributes.location
// Skip minutes without a published ceiling (on-demand pseudo-reservations, not-yet-published data); never treat them as 0
| WHERE ceiling IS NOT NULL AND ceiling > 0
// A minute with a ceiling but no reported allocation is an idle reservation
| EVAL allocated = COALESCE(allocated, 0)
| EVAL utilisation_pct = allocated * 100.0 / ceiling
// Customise: a minute counts as saturated at >= 95% of the autoscale max (slots/max_assigned)
| STATS saturated_minutes = COUNT(*) WHERE utilisation_pct >= 95.0,
        observed_minutes = COUNT(*),
        avg_utilisation_pct = ROUND(AVG(utilisation_pct), 1),
        peak_allocated_slots = MAX(allocated),
        max_assigned_slots = LAST(ceiling, @timestamp)
    BY attributes.reservation, resource.attributes.location

breach.segment:
// Customise: alert when saturated for >= 15 one-minute samples in the window
// (slot metrics publish up to ~7 minutes late, so a 30-minute window holds ~23 visible minutes)
WHERE saturated_minutes >= 15
| SORT saturated_minutes DESC, avg_utilisation_pct DESC
| LIMIT 50
